1	import { mkdir, readFile, writeFile, access, copyFile } from "node:fs/promises";
2	import { execSync } from "node:child_process";
3	
4	// JSON.stringify is used as a safe shell-arg quoter for known-shape strings
5	// like Jira branch names; treat any string passed to execSync that way.
6	
7	const mode = process.argv[2];
8	if (!mode) {
9	  throw new Error("Usage: jira-dispatch.mjs <prepare-dispatch|record-run|commit-changes|ensure-pr|comment-result>");
10	}
11	
12	const env = process.env;
13	
14	let jiraBaseUrl;
15	let jiraHeaders;
16	
17	run().catch((err) => {
18	  console.error(err);
19	  process.exit(1);
20	});
21	
22	async function run() {
23	  if (mode === "prepare-dispatch") return prepareDispatch();
24	  if (mode === "record-run") return recordRun();
25	  if (mode === "commit-changes") return commitChanges();
26	  if (mode === "ensure-pr") return ensurePr();
27	  if (mode === "comment-result") return commentResult();
28	  throw new Error(`Unknown mode: ${mode}`);
29	}
