37	function initJira() {
38	  const baseUrl = requireEnv("JIRA_BASE_URL").replace(/\/+$/, "");
39	  const email = requireEnv("JIRA_EMAIL");
40	  const token = requireEnv("JIRA_API_TOKEN");
41	  jiraBaseUrl = baseUrl;
42	  jiraHeaders = {
43	    Authorization: `Basic ${Buffer.from(`${email}:${token}`).toString("base64")}`,
44	    Accept: "application/json",
45	    "Content-Type": "application/json",
46	  };
47	}
