49	async function fetchJson(url, options) {
50	  const response = await fetch(url, options);
51	  if (!response.ok) {
52	    const body = await response.text();
53	    throw new Error(`HTTP ${response.status} ${response.statusText} for ${url}: ${body}`);
54	  }
55	  return response.json();
56	}
