58	async function transitionToInProgress(key, issue) {
59	  const category = lower(issue?.fields?.status?.statusCategory?.key);
60	  if (category === "indeterminate" || category === "done") {
61	    console.log(`Skipping In Progress transition for ${key}: status category is "${category}".`);
62	    return;
63	  }
64	
65	  let transitions;
66	  try {
67	    const data = await fetchJson(
68	      `${jiraBaseUrl}/rest/api/3/issue/${encodeURIComponent(key)}/transitions`,
69	      { headers: jiraHeaders },
70	    );
71	    transitions = Array.isArray(data?.transitions) ? data.transitions : [];
72	  } catch (err) {
73	    console.warn(`Failed to fetch transitions for ${key}: ${err.message}`);
74	    return;
75	  }
76	
77	  const target =
78	    transitions.find((t) => lower(t?.to?.statusCategory?.key) === "indeterminate") ||
79	    transitions.find((t) => lower(t?.name) === "in progress");
80	
81	  if (!target) {
82	    console.warn(`No "In Progress" transition available for ${key}; continuing without status change.`);
83	    return;
84	  }
85	
86	  try {
87	    const response = await fetch(
88	      `${jiraBaseUrl}/rest/api/3/issue/${encodeURIComponent(key)}/transitions`,
89	      {
90	        method: "POST",
91	        headers: jiraHeaders,
92	        body: JSON.stringify({ transition: { id: target.id } }),
93	      },
94	    );
95	    if (!response.ok) {
96	      const body = await response.text().catch(() => "");
97	      console.warn(`Failed to transition ${key} via "${target.name}" (id=${target.id}): HTTP ${response.status} ${response.statusText}${body ? ` ${body}` : ""}`);
98	      return;
99	    }
100	    console.log(`Transitioned ${key} to In Progress via "${target.name}" (id=${target.id}).`);
101	  } catch (err) {
102	    console.warn(`Failed to transition ${key} via "${target.name}" (id=${target.id}): ${err.message}`);
103	  }
104	}
105	
106	async function appendGithubEnv(values) {
107	  const file = env.GITHUB_ENV;
108	  if (!file) return;
109	  const body = Object.entries(values)
110	    .map(([k, v]) => {
111	      const s = String(v ?? "");
112	      if (s.includes("\n")) return `${k}<<EOF_${k}\n${s}\nEOF_${k}`;
113	      return `${k}=${s}`;
114	    })
115	    .join("\n");
116	  await writeFile(file, body + "\n", { flag: "a" });
117	}
