137	function nowIso() {
138	  return new Date().toISOString();
139	}
140	
141	function compactStamp() {
142	  return new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "Z");
143	}
144	
145	function lower(s) {
146	  return String(s ?? "").toLowerCase();
147	}
148	
149	function tableRow(value) {
150	  return String(value || "-").replace(/\|/g, "\\|").replace(/\n/g, "<br>");
151	}
152	
153	function normalizeIssueKey(key) {
154	  const normalized = String(key || "").trim().toUpperCase();
155	  if (!/^[A-Z][A-Z0-9]+-\d+$/.test(normalized)) {
156	    throw new Error(`Invalid Jira issue key: ${key}`);
157	  }
158	  return normalized;
159	}
160	
161	function determineKind(issue) {
162	  const labels = (issue.fields?.labels ?? []).map(lower);
163	  if (labels.includes("claude:answer")) return "answer";
164	  if (labels.includes("claude:pr")) return "pr";
165	  const type = lower(issue.fields?.issuetype?.name);
166	  if (type === "question") return "answer";
167	  return "pr";
168	}
