170	async function prepareDispatch() {
171	  initJira();
172	  const key = normalizeIssueKey(requireEnv("ISSUE_KEY"));
173	
174	  const issue = await fetchJson(
175	    `${jiraBaseUrl}/rest/api/3/issue/${encodeURIComponent(key)}?fields=summary,description,status,assignee,reporter,priority,issuetype,labels,components,created,updated,comment&expand=renderedFields`,
176	    { headers: jiraHeaders },
177	  );
178	
179	  await transitionToInProgress(key, issue);
180	
181	  const fields = issue.fields ?? {};
182	  const summary = fields.summary || key;
183	  const kind = determineKind(issue);
184	  const branchName = `tdf/${key.toLowerCase()}`;
185	
186	  // For PR mode, switch to the existing PR branch if one exists on origin so
187	  // that prior state.json, plan.md, transcript.md, and any code changes are
188	  // visible to this run. Done before any file writes to avoid untracked-file
189	  // collisions with `git checkout`.
190	  if (kind === "pr") {
191	    let branchExists = false;
192	    try {
193	      execSync(`git ls-remote --exit-code --heads origin ${JSON.stringify(branchName)}`, { stdio: "ignore" });
194	      branchExists = true;
195	    } catch {
196	      branchExists = false;
197	    }
198	    if (branchExists) {
199	      console.log(`Existing branch ${branchName} found on origin; checking out.`);
200	      execSync(`git fetch origin ${JSON.stringify(branchName)}`, { stdio: "inherit" });
201	      execSync(`git checkout -B ${JSON.stringify(branchName)} origin/${branchName}`, { stdio: "inherit" });
202	    } else {
203	      console.log(`No existing branch ${branchName}; will create from main on commit.`);
204	    }
205	  }
206	
207	  const ticketFolder = `spec/${key}`;
208	  const stateFile = `${ticketFolder}/state.json`;
209	  const transcriptFile = `${ticketFolder}/transcript.md`;
210	  const specFile = `${ticketFolder}/spec.md`;
211	  const planFile = `${ticketFolder}/plan.md`;
212	  const responseFile = `${ticketFolder}/response.md`;
213	  const runDir = `${ticketFolder}/runs/${compactStamp()}-${env.GITHUB_RUN_ID || "local"}`;
214	  const promptFile = `${runDir}/prompt.md`;
215	
216	  await mkdir(runDir, { recursive: true });
217	
218	  let isNew = true;
219	  let lastSessionId = "";
220	  if (await pathExists(stateFile)) {
221	    isNew = false;
222	    const state = await readJsonOrEmpty(stateFile);
223	    lastSessionId = state.last_session_id || "";
224	  } else {
225	    await writeFile(
226	      stateFile,
227	      JSON.stringify({ ticket_id: key, run_count: 0, kind, branch: branchName }, null, 2) + "\n",
228	      "utf8",
229	    );
230	  }
231	
232	  if (!(await pathExists(transcriptFile))) {
233	    await writeFile(transcriptFile, `# ${key} Transcript\n`, "utf8");
234	  }
235	
236	  const comments = issue.fields?.comment?.comments ?? [];
237	  await writeFile(specFile, buildSpec({ issue, comments, key }), "utf8");
238	
239	  const prompt = buildPrompt({
240	    key,
241	    summary,
242	    ticketFolder,
243	    kind,
244	    isNew,
245	    specFile,
246	    planFile,
247	    responseFile,
248	    transcriptFile,
249	  });
250	  await writeFile(promptFile, prompt, "utf8");
251	
252	  let claudeArgs = "--max-turns 60 --permission-mode bypassPermissions";
253	  if (lastSessionId) claudeArgs += ` --resume ${lastSessionId}`;
254	
255	  await mkdir(`${requireEnv("HOME")}/.claude/projects`, { recursive: true });
256	
257	  await appendGithubEnv({
258	    SHOULD_RUN: "true",
259	    ISSUE_KEY: key,
260	    ISSUE_TITLE: summary,
261	    JIRA_ISSUE_URL: `${jiraBaseUrl}/browse/${key}`,
262	    KIND: kind,
263	    BRANCH_NAME: branchName,
264	    IS_NEW: isNew ? "true" : "false",
265	    LAST_SESSION_ID: lastSessionId,
266	    TICKET_FOLDER: ticketFolder,
267	    STATE_FILE: stateFile,
268	    TRANSCRIPT_FILE: transcriptFile,
269	    SPEC_FILE: specFile,
270	    PLAN_FILE: planFile,
271	    RESPONSE_FILE: responseFile,
272	    RUN_DIR: runDir,
273	    PROMPT_FILE: promptFile,
274	    CLAUDE_ARGS: claudeArgs,
275	  });
276	
277	  console.log(`Prepared dispatch for ${key} (kind=${kind} new=${isNew} last_session=${lastSessionId || "<none>"})`);
278	}
