280	async function recordRun() {
281	  const stateFile = requireEnv("STATE_FILE");
282	  const transcriptFile = requireEnv("TRANSCRIPT_FILE");
283	  const responseFile = env.RESPONSE_FILE || "";
284	  const promptFile = env.PROMPT_FILE || "";
285	  const runDir = env.RUN_DIR || "";
286	  const isNew = env.IS_NEW === "true";
287	  const kind = env.KIND || "pr";
288	  const conclusion = env.CONCLUSION || "unknown";
289	  const lastSessionId = env.LAST_SESSION_ID || "";
290	  const actionSessionId = env.ACTION_SESSION_ID || "";
291	  const executionFile = env.EXECUTION_FILE || "";
292	
293	  let newSessionId = actionSessionId;
294	  let assistantText = "";
295	
296	  if (executionFile && (await pathExists(executionFile))) {
297	    try {
298	      const raw = await readFile(executionFile, "utf8");
299	      const entries = parseExecutionFile(raw);
300	      if (!newSessionId) {
301	        for (const e of entries) {
302	          if (e?.session_id) newSessionId = e.session_id;
303	        }
304	      }
305	      for (const e of entries) {
306	        if (e?.type === "assistant") {
307	          for (const part of e?.message?.content ?? []) {
308	            if (part?.type === "text" && typeof part.text === "string") {
309	              assistantText = part.text;
310	            }
311	          }
312	        }
313	      }
314	      if (runDir) {
315	        await mkdir(runDir, { recursive: true });
316	        await copyFile(executionFile, `${runDir}/execution.json`);
317	      }
318	    } catch (err) {
319	      console.warn(`Failed to parse execution_file: ${err.message}`);
320	    }
321	  }
322	
323	  if (runDir) {
324	    if (responseFile && (await pathExists(responseFile))) {
325	      await copyFile(responseFile, `${runDir}/response.md`);
326	    }
327	    if (promptFile && (await pathExists(promptFile))) {
328	      await copyFile(promptFile, `${runDir}/prompt.md`);
329	    }
330	  }
331	
332	  const now = nowIso();
333	  const rotated = lastSessionId && newSessionId && lastSessionId !== newSessionId;
334	
335	  const state = await readJsonOrEmpty(stateFile);
336	  state.ticket_id = state.ticket_id || env.ISSUE_KEY || "";
337	  state.last_session_id = newSessionId || "";
338	  state.prev_session_id = lastSessionId || null;
339	  state.last_run_at = now;
340	  state.last_conclusion = conclusion;
341	  state.last_kind = kind;
342	  state.run_count = (state.run_count || 0) + 1;
343	  if (env.BRANCH_NAME) state.branch = env.BRANCH_NAME;
344	  state.kind = kind;
345	  await writeFile(stateFile, JSON.stringify(state, null, 2) + "\n", "utf8");
346	
347	  const summarySnippet = (assistantText || "").trim().split("\n").slice(0, 12).join("\n  ");
348	  const block = [
349	    "",
350	    `## Run ${now}`,
351	    `- run_kind: ${isNew ? "new" : "continuation"}`,
352	    `- prev_session_id: ${lastSessionId || "<none>"}`,
353	    `- new_session_id: ${newSessionId || "<none>"}`,
354	    `- session_id_rotated: ${rotated ? "true" : "false"}`,
355	    `- conclusion: ${conclusion}`,
356	    `- run_dir: ${runDir || "<none>"}`,
357	    `- assistant_summary:\n  ${summarySnippet || "<empty>"}`,
358	    "",
359	  ].join("\n");
360	  await writeFile(transcriptFile, block, { flag: "a" });
361	
362	  await appendGithubEnv({ NEW_SESSION_ID: newSessionId });
363	  console.log(`Recorded run for ${env.ISSUE_KEY}: session=${newSessionId || "<none>"}`);
364	}
365	
366	function parseExecutionFile(raw) {
367	  const trimmed = raw.trim();
368	  if (!trimmed) return [];
369	  if (trimmed.startsWith("[")) {
370	    try {
371	      const arr = JSON.parse(trimmed);
372	      return Array.isArray(arr) ? arr : [];
373	    } catch {
374	      // fall through to NDJSON
375	    }
376	  }
377	  return trimmed
378	    .split("\n")
379	    .filter(Boolean)
380	    .map((line) => {
381	      try {
382	        return JSON.parse(line);
383	      } catch {
384	        return null;
385	      }
386	    })
387	    .filter(Boolean);
388	}
