390	function commitChanges() {
391	  const kind = env.KIND || "pr";
392	  const branchName = requireEnv("BRANCH_NAME");
393	  const issueKey = requireEnv("ISSUE_KEY");
394	  const ticketFolder = requireEnv("TICKET_FOLDER");
395	  const runId = env.GITHUB_RUN_ID || "";
396	
397	  sh("rm -f output.txt");
398	  sh('git config user.name "github-actions[bot]"');
399	  sh('git config user.email "41898282+github-actions[bot]@users.noreply.github.com"');
400	
401	  if (kind === "pr") {
402	    sh(`git checkout -B "${branchName}"`);
403	    sh("git add -A");
404	    if (gitNothingStaged()) {
405	      console.log("No changes to commit on PR branch");
406	      return appendGithubEnv({ COMMITTED: "false" });
407	    }
408	    sh(`git commit -m "${issueKey}: claude-code update (run ${runId})"`);
409	    sh(`git push origin "HEAD:${branchName}"`);
410	    return appendGithubEnv({ COMMITTED: "true" });
411	  }
412	
413	  sh(`git add -A "${ticketFolder}"`);
414	  if (gitNothingStaged()) {
415	    console.log("No artefact changes to commit on main");
416	    return appendGithubEnv({ COMMITTED: "false" });
417	  }
418	  sh(`git commit -m "${issueKey}: update ticket artefacts (run ${runId})"`);
419	  sh("git push origin HEAD:main");
420	  return appendGithubEnv({ COMMITTED: "true" });
421	}
422	
423	function gitNothingStaged() {
424	  try {
425	    execSync("git diff --cached --quiet", { stdio: "ignore" });
426	    return true;
427	  } catch {
428	    return false;
429	  }
430	}
431	
432	function sh(cmd) {
433	  execSync(cmd, { stdio: ["ignore", "inherit", "inherit"] });
434	}
435	
436	async function ensurePr() {
437	  if ((env.KIND || "pr") !== "pr") {
438	    console.log("Not PR mode, skipping ensure-pr");
439	    return;
440	  }
441	  if (env.COMMITTED !== "true") {
442	    console.log("No commit happened on this run; skipping PR.");
443	    return;
444	  }
445	
446	  const issueKey = requireEnv("ISSUE_KEY");
447	  const issueTitle = env.ISSUE_TITLE || issueKey;
448	  const branchName = requireEnv("BRANCH_NAME");
449	  const repo = requireEnv("GITHUB_REPOSITORY");
450	  const repoOwner = repo.split("/")[0];
451	  const ghToken = requireEnv("GH_TOKEN");
452	
453	  const headers = {
454	    Accept: "application/vnd.github+json",
455	    Authorization: `Bearer ${ghToken}`,
456	    "X-GitHub-Api-Version": "2022-11-28",
457	    "User-Agent": "tdf-dispatch",
458	  };
459	
460	  const listUrl = `https://api.github.com/repos/${repo}/pulls?state=open&base=main&head=${repoOwner}:${branchName}`;
461	  const existing = await fetchJson(listUrl, { headers });
462	  let prUrl = (Array.isArray(existing) && existing[0] && existing[0].html_url) || "";
463	
464	  if (!prUrl) {
465	    const body = [
466	      `Automated Claude Code update for ${issueKey}.`,
467	      "",
468	      `Jira: ${env.JIRA_ISSUE_URL || ""}`,
469	      `Ticket folder: \`${env.TICKET_FOLDER || ""}\``,
470	      "",
471	      "Review and merge when ready.",
472	    ].join("\n");
473	
474	    const created = await fetchJson(`https://api.github.com/repos/${repo}/pulls`, {
475	      method: "POST",
476	      headers: { ...headers, "Content-Type": "application/json" },
477	      body: JSON.stringify({
478	        title: `${issueKey}: ${issueTitle}`,
479	        head: branchName,
480	        base: "main",
481	        body,
482	      }),
483	    });
484	    prUrl = created.html_url;
485	  }
486	
487	  await appendGithubEnv({ PR_URL: prUrl });
488	  console.log(`Pull request: ${prUrl}`);
489	}
490	
491	async function commentResult() {
492	  initJira();
493	  const issueKey = requireEnv("ISSUE_KEY");
494	  const kind = env.KIND || "pr";
495	  const branchName = env.BRANCH_NAME || "";
496	  const responseFile = env.RESPONSE_FILE || "";
497	  const stateFile = env.STATE_FILE || "";
498	  const repo = env.GITHUB_REPOSITORY || "";
499	  const prUrl = env.PR_URL || "";
500	  let conclusion = env.CONCLUSION || "";
501	  if (!conclusion && stateFile) {
502	    const state = await readJsonOrEmpty(stateFile);
503	    conclusion = state.last_conclusion || "unknown";
504	  }
505	  if (!conclusion) conclusion = "unknown";
506	
507	  const content = [];
508	
509	  if (kind === "pr") {
510	    content.push(paragraph(`[TDF-bot] Claude Code processed ${issueKey} (conclusion: ${conclusion}).`));
511	    if (branchName && repo) {
512	      content.push(linkParagraph("Branch", `https://github.com/${repo}/tree/${encodeURIComponent(branchName)}`));
513	    }
514	    if (prUrl) content.push(linkParagraph("Pull request", prUrl));
515	    if (env.COMMITTED === "false") {
516	      content.push(paragraph("No repository changes were committed on this run."));
517	    }
518	    if (responseFile && (await pathExists(responseFile))) {
519	      const text = (await readFile(responseFile, "utf8")).trim();
520	      if (text) content.push(...markdownToAdfBlocks(text));
521	    }
522	  } else {
523	    content.push(paragraph(`[TDF-bot] Claude Code answer for ${issueKey} (conclusion: ${conclusion}):`));
524	    if (responseFile && (await pathExists(responseFile))) {
525	      const text = (await readFile(responseFile, "utf8")).trim();
526	      if (text) content.push(...markdownToAdfBlocks(text));
527	      else content.push(paragraph("_Empty response._"));
528	    } else {
529	      content.push(paragraph("_No response file produced._"));
530	    }
531	  }
532	
533	  await fetchJson(`${jiraBaseUrl}/rest/api/3/issue/${encodeURIComponent(issueKey)}/comment`, {
534	    method: "POST",
535	    headers: jiraHeaders,
536	    body: JSON.stringify({ body: { type: "doc", version: 1, content } }),
537	  });
538	  console.log(`Posted comment to ${issueKey}`);
539	}
540	
541	function paragraph(text) {
542	  return { type: "paragraph", content: [{ type: "text", text }] };
543	}
544	
545	function linkParagraph(label, href) {
546	  return {
547	    type: "paragraph",
548	    content: [
549	      { type: "text", text: `${label}: ` },
550	      { type: "text", text: href, marks: [{ type: "link", attrs: { href } }] },
551	    ],
552	  };
553	}
554	
555	function markdownToAdfBlocks(text) {
556	  const blocks = String(text)
557	    .slice(0, 30000)
558	    .split(/\n{2,}/)
559	    .map((s) => s.trim())
560	    .filter(Boolean);
561	  return blocks.map((block) => {
562	    const lines = block.split("\n");
563	    return {
564	      type: "paragraph",
565	      content: lines.flatMap((line, i) => [
566	        ...(i === 0 ? [] : [{ type: "hardBreak" }]),
567	        { type: "text", text: line },
568	      ]),
569	    };
570	  });
571	}
572	
573	function buildSpec({ issue, comments, key }) {
574	  const fields = issue.fields ?? {};
575	  const description = adfToMarkdown(fields.description).trim() || "_No description provided._";
576	  const renderedComments = (comments ?? []).map((c) => {
577	    const author = c.author?.displayName || "<unknown>";
578	    const created = c.created || "";
579	    const body = adfToMarkdown(c.body).trim() || "_<empty>_";
580	    return `### ${author} on ${created}\n\n${body}`;
581	  });
582	  return [
583	    `# ${key}: ${fields.summary ?? "Untitled Jira issue"}`,
584	    "",
585	    `Generated from Jira on ${nowIso()}.`,
586	    "",
587	    "## Issue Details",
588	    "",
589	    "| Field | Value |",
590	    "|---|---|",
591	    `| Key | ${tableRow(key)} |`,
592	    `| Title | ${tableRow(fields.summary)} |`,
593	    `| Type | ${tableRow(fields.issuetype?.name)} |`,
594	    `| Status | ${tableRow(fields.status?.name)} |`,
595	    `| Priority | ${tableRow(fields.priority?.name)} |`,
596	    `| Assignee | ${tableRow(fields.assignee?.displayName)} |`,
597	    `| Reporter | ${tableRow(fields.reporter?.displayName)} |`,
598	    `| Labels | ${tableRow((fields.labels ?? []).join(", "))} |`,
599	    `| Components | ${tableRow((fields.components ?? []).map((c) => c.name).join(", "))} |`,
600	    `| Created | ${tableRow(fields.created)} |`,
601	    `| Updated | ${tableRow(fields.updated)} |`,
602	    "",
603	    "## Description",
604	    "",
605	    description,
606	    "",
607	    `## Comments (${(comments ?? []).length})`,
608	    "",
609	    renderedComments.length ? renderedComments.join("\n\n") : "_No comments._",
610	    "",
611	  ].join("\n");
612	}
613	
614	function buildPrompt({ key, summary, ticketFolder, kind, isNew, specFile, planFile, responseFile, transcriptFile }) {
615	  const goal =
616	    kind === "pr"
617	      ? [
618	          "- Make the smallest correct repository changes to satisfy the ticket.",
619	          `- Update \`${planFile}\` with the implementation plan.`,
620	          `- Write a concise Jira-facing summary to \`${responseFile}\` (what changed, why, risks). Do not include logs or secrets.`,
621	          "- Do not create or merge pull requests; the workflow does that.",
622	        ].join("\n")
623	      : [
624	          `- Do not edit any file outside \`${ticketFolder}\`.`,
625	          `- Update \`${planFile}\` with reasoning if it helps.`,
626	          `- Write the complete answer to \`${responseFile}\` in markdown that renders correctly in Jira.`,
627	        ].join("\n");
628	
629	  const continuationNote = isNew
630	    ? ""
631	    : `- This is a continuation. If your in-memory session is missing, rebuild context from \`${transcriptFile}\`, \`${planFile}\`, and the \`runs/\` folder under the ticket.\n`;
632	
633	  return [
634	    `You are running inside \`${env.GITHUB_REPOSITORY}\` for Jira ticket \`${key}: ${summary}\`.`,
635	    "",
636	    "Read `CLAUDE.md` for repository conventions before touching files.",
637	    "",
638	    `Ticket folder: \`${ticketFolder}\`.`,
639	    `- \`${specFile}\`: a fresh snapshot of the Jira ticket and its comments. Read it. Do not edit it.`,
640	    `- \`${planFile}\`: implementation plan. You own this file. Update it as you go.`,
641	    `- \`${transcriptFile}\`: rolling history of prior runs. Read it for context if needed.`,
642	    `- \`${responseFile}\`: the message that will be posted back to Jira. You own this file.`,
643	    "",
644	    `Run kind: \`${kind}\` (${kind === "pr" ? "expects code/config changes plus a PR" : "answer-only, no code changes outside the ticket folder"}).`,
645	    `Run mode: \`${isNew ? "NEW" : "CONTINUATION"}\`.`,
646	    "",
647	    "Goal:",
648	    goal,
649	    "",
650	    "Constraints:",
651	    "- Never expose, print, or commit secrets.",
652	    "- Do not switch branches.",
653	    "- Keep tool usage minimal.",
654	    continuationNote,
655	  ].join("\n");
656	}
657	
658	function adfToMarkdown(node) {
659	  if (!node) return "";
660	  if (Array.isArray(node)) return node.map(adfToMarkdown).join("");
661	
662	  switch (node.type) {
663	    case "doc":
664	      return blockContent(node).join("\n\n");
665	    case "paragraph":
666	      return inlineContent(node);
667	    case "heading":
668	      return `${"#".repeat(node.attrs?.level ?? 2)} ${inlineContent(node)}`;
669	    case "bulletList":
670	      return listContent(node, "-");
671	    case "orderedList":
672	      return orderedListContent(node);
673	    case "listItem":
674	      return blockContent(node).join("\n");
675	    case "blockquote":
676	      return blockContent(node)
677	        .join("\n")
678	        .split("\n")
679	        .map((line) => `> ${line}`)
680	        .join("\n");
681	    case "codeBlock":
682	      return `\`\`\`\n${textContent(node)}\n\`\`\``;
683	    case "rule":
684	      return "---";
685	    case "hardBreak":
686	      return "\n";
687	    case "text":
688	      return applyMarks(node.text ?? "", node.marks ?? []);
689	    default:
690	      return blockContent(node).join("\n");
691	  }
692	}
693	
694	function blockContent(node) {
695	  return (node.content ?? []).map(adfToMarkdown).filter(Boolean);
696	}
697	
698	function inlineContent(node) {
699	  return (node.content ?? []).map(adfToMarkdown).join("");
700	}
701	
702	function listContent(node, marker) {
703	  return (node.content ?? [])
704	    .map((item) =>
705	      adfToMarkdown(item)
706	        .split("\n")
707	        .map((line, idx) => (idx === 0 ? `${marker} ${line}` : `  ${line}`))
708	        .join("\n"),
709	    )
710	    .join("\n");
711	}
712	
713	function orderedListContent(node) {
714	  const start = node.attrs?.order ?? 1;
715	  return (node.content ?? [])
716	    .map((item, idx) =>
717	      adfToMarkdown(item)
718	        .split("\n")
719	        .map((line, lineIdx) => (lineIdx === 0 ? `${start + idx}. ${line}` : `   ${line}`))
720	        .join("\n"),
721	    )
722	    .join("\n");
723	}
724	
725	function textContent(node) {
726	  if (node.type === "text") return node.text ?? "";
727	  return (node.content ?? []).map(textContent).join("");
728	}
729	
730	function applyMarks(text, marks) {
731	  return marks.reduce((value, mark) => {
732	    switch (mark.type) {
733	      case "strong":
734	        return `**${value}**`;
735	      case "em":
736	        return `_${value}_`;
737	      case "code":
738	        return `\`${value}\``;
739	      case "link":
740	        return `[${value}](${mark.attrs?.href ?? value})`;
741	      default:
742	        return value;
743	    }
744	  }, text);
745	}
